targets.query:
from(bucket: "cloudbktcp")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["_measurement"] == "ePower")
  |> filter(fn: (r) => r["eMeter"] == "VHWP")
  |> filter(fn: (r) => r["_field"] == "sumWh")
  //|> increase()
  //|> aggregateWindow(every: 5m, fn: last, offset: -1h)
 // |> duplicate(column: "_stop", as: "_time")
  //|> max()
  |> aggregateWindow(every: v.windowPeriod, fn: last, createEmpty: false)
  |> increase()
  |> yield(name: "increase")

from(bucket: "bktRP4GH")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["_measurement"] == "ePowerWP")
  |> filter(fn: (r) => r["meter"] == "WPGH")
  |> filter(fn: (r) => r["mptype"] == "totalEnergy")
  //|> increase()
  //|> aggregateWindow(every: 5m, fn: last, offset: -1h)
 // |> duplicate(column: "_stop", as: "_time")
  //|> max()
  |> aggregateWindow(every: v.windowPeriod, fn: last, createEmpty: false)
  |> increase()
  |> yield(name: "increase")

from(bucket: "cloudbktcp")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["_measurement"] == "Gas")
  |> filter(fn: (r) => r["_field"] == "gascnt")
  |> increase()
  |> aggregateWindow(every: v.windowPeriod, column: "_field", fn: last, createEmpty: false)

 |> map(fn: (r) => ({
   r with
    _value: float(v: r._value)*0.108
     }))
 // |> yield(name: "gas")
